{"explanation":"The sine graph is wavy because it models a quantity that repeats smoothly: as the input increases, the output rises and falls in a regular cycle. It comes from tracking one coordinate of a point moving around a circle—the height goes up, reaches a maximum, comes back down, reaches a minimum, then repeats.","manimCode":"const circle = new Circle({ radius: 1.25, color: BLUE });
circle.moveTo([-3.2, 0.1, 0]);
const center = new Dot({ point: [-3.2, 0.1, 0], color: WHITE });
const marker = new Dot({ point: [-3.2, 1.35, 0], color: YELLOW });
const radiusLine = new Polygon({ vertices: [[-3.2, 0.1, 0], [-3.2, 1.35, 0]], color: YELLOW });
radiusLine.setStrokeWidth(2).setFillOpacity(0);
const ax = new Axes({ xRange: [0, 2 * Math.PI, Math.PI], yRange: [-1.5, 1.5, 1], xLength: 7, yLength: 3.4, tips: false });
ax.moveTo([2.5, 0, 0]);
const curve = ax.plot(x => Math.sin(x), { color: ORANGE, numSamples: 300 });
scene.add(circle, center, marker, radiusLine, ax, curve);
makeDraggable(marker, scene, { onDrag: (mob) => {
  const [x, y] = mob.getCenter();
  const dx = x + 3.2, dy = y - 0.1;
  const theta = Math.atan2(dy, dx);
  const px = -3.2 + 1.25 * Math.cos(theta), py = 0.1 + 1.25 * Math.sin(theta);
  mob.moveTo([px, py, 0]);
  radiusLine.setVertices([[-3.2, 0.1, 0], [px, py, 0]]);
} });
await scene.wait(999999);"}

